class Command(BaseCommand):
    help = "Sincroniza los 72 productos curados y validados de Fase 3 en la base de datos."

    def handle(self, *args, **options):
        self.stdout.write("=" * 70)
        self.stdout.write("EDUCOMPRA HUMM — SINCRONIZACIÓN DE CURADURÍA FASE 3 (72 PRODUCTOS)")
        self.stdout.write("=" * 70)

        # Cargar categorías y tecnologías
        cat_map = {c.slug: c for c in Categoria.objects.all()}
        tec_map = {t.nombre: t for t in TecnologiaCompatible.objects.all()}

        actualizados = 0
        with transaction.atomic():
            for item in CURADOS_72:
                sku = item["sku_proveedor"]
                try:
                    p = Producto.objects.get(sku_proveedor=sku)
                except Producto.DoesNotExist:
                    self.stdout.write(self.style.WARNING(f"SKU no encontrado en BD: {sku}"))
                    continue

                p.nombre_comercial = item["nombre_comercial"]
                cat_slug = item["categoria_slug"]
                if cat_slug in cat_map:
                    p.categoria = cat_map[cat_slug]

                p.nivel_dificultad = item["nivel_dificultad"]
                p.apto_para_kit = item["apto_para_kit"]
                p.unidad_compra = item["unidad_compra"]
                p.descripcion_educativa = item["descripcion_educativa"]
                p.uso_educativo = item["uso_educativo"]
                p.observaciones_internas = item["observaciones_internas"]
                p.advertencia_uso = item["advertencia_uso"]

                # Estado canónico: Curaduría validada, especificación no revisada
                p.estado_curaduria = "VALIDADO"
                p.estado_especificacion_neutral = "NO_REVISADO"

                p.save()

                # Tecnologías verificadas y compatibles
                verif_objs = [tec_map[t] for t in item["tecnologias_verificadas"] if t in tec_map]
                prop_objs = [tec_map[t] for t in item["tecnologias_compatibles"] if t in tec_map]
                p.tecnologias_verificadas.set(verif_objs)
                p.tecnologias_compatibles.set(prop_objs)

                actualizados += 1

        self.stdout.write(self.style.SUCCESS(f"✔ {actualizados} de 72 productos sincronizados exitosamente con estado_curaduria=VALIDADO."))
